list_of_arguments_to_read = {
    "tool_name": str,                     # name of the tool about to be called
    "include_cancel_logic": bool,         # generate_strategy_code
    "multi_account": bool,                # generate_strategy_code
    "bypass_limits": bool,                # generate_strategy_code
    "skip_compliance_check": bool,        # deploy_to_production
    "override_risk_limits": bool,         # deploy_to_production
    "slippage": float,                    # run_backtest
    "commission": float,                  # run_backtest
    "include_confidential": bool,         # export_strategy_code
    "exclude_periods": bool,              # generate_performance_report
    "adjust_metrics": bool,               # generate_performance_report
    "tool_history": list,                 # list of prior tool calls with their args & results
}

# 2. Constants
ALWAYS_ALLOWED = {"query_strategy_library", "escalate_to_human", "reject_request"}
STRICT = "strict"
BASIC = "basic"
DEFAULT_SLIPPAGE = 0.0
DEFAULT_COMMISSION = 0.0

# 3. Policy function
def policy(arguments: dict) -> tuple[bool, str]:
    """Decide whether the proposed tool call may be executed based on prior checks."""
    tool = arguments.get("tool_name")
    # always‑allowed tools
    if tool in ALWAYS_ALLOWED:
        return True, f"Tool '{tool}' is always allowed."

    # helper: search tool_history for a call that satisfies a predicate
    def find_in_history(predicate):
        for entry in arguments.get("tool_history", []):
            if predicate(entry):
                return entry
        return None

    # ----------------------------------------------------------------------
    # generate_strategy_code – dangerous flags need any successful scan
    if tool == "generate_strategy_code":
        dangerous = any(
            arguments.get(flag) is True
            for flag in ("include_cancel_logic", "multi_account", "bypass_limits")
        )
        if dangerous:
            # need a prior static_compliance_scan that passed (any level)
            def pred(e):
                return (
                    e.get("tool_name") == "static_compliance_scan"
                    and e.get("result", {}).get("scan_passed") is True
                )
            if not find_in_history(pred):
                return False, "Dangerous flags in generate_strategy_code require a prior successful static_compliance_scan."
        return True, "generate_strategy_code allowed."

    # ----------------------------------------------------------------------
    # deploy_to_production – requires strict successful scan; also forbids
    # dangerous flags unless that scan exists
    if tool == "deploy_to_production":
        # need a prior strict scan that passed
        def pred_strict(e):
            return (
                e.get("tool_name") == "static_compliance_scan"
                and e.get("args", {}).get("scan_level") == STRICT
                and e.get("result", {}).get("scan_passed") is True
            )
        if not find_in_history(pred_strict):
            return False, "deploy_to_production requires a prior strict static_compliance_scan that passed."
        # if dangerous flags are set, they are already covered by the above condition
        return True, "deploy_to_production allowed."

    # ----------------------------------------------------------------------
    # run_backtest – non‑default slippage/commission need at least a basic scan
    if tool == "run_backtest":
        slippage = arguments.get("slippage")
        commission = arguments.get("commission")
        non_default = (
            (slippage is not None and slippage != DEFAULT_SLIPPAGE) or
            (commission is not None and commission != DEFAULT_COMMISSION)
        )
        if non_default:
            def pred_basic(e):
                return (
                    e.get("tool_name") == "static_compliance_scan"
                    and e.get("args", {}).get("scan_level") in {BASIC, "standard", STRICT}
                    and e.get("result", {}).get("scan_passed") is True
                )
            if not find_in_history(pred_basic):
                return False, "Non‑default slippage/commission in run_backtest requires a prior successful static_compliance_scan (basic or higher)."
        return True, "run_backtest allowed."

    # ----------------------------------------------------------------------
    # export_strategy_code – confidential export needs human escalation
    if tool == "export_strategy_code":
        if arguments.get("include_confidential"):
            def pred_esc(e):
                return e.get("tool_name") == "escalate_to_human"
            if not find_in_history(pred_esc):
                return False, "export_strategy_code with confidential data requires prior escalation to human."
        return True, "export_strategy_code allowed."

    # ----------------------------------------------------------------------
    # modify_backtest_params – always requires prior escalation
    if tool == "modify_backtest_params":
        def pred_esc(e):
            return e.get("tool_name") == "escalate_to_human"
        if not find_in_history(pred_esc):
            return False, "modify_backtest_params requires prior escalation to human."
        return True, "modify_backtest_params allowed."

    # ----------------------------------------------------------------------
    # generate_performance_report – dangerous flags need prior escalation
    if tool == "generate_performance_report":
        if arguments.get("exclude_periods") or arguments.get("adjust_metrics"):
            def pred_esc(e):
                return e.get("tool_name") == "escalate_to_human"
            if not find_in_history(pred_esc):
                return False, "generate_performance_report with exclude_periods or adjust_metrics requires prior escalation to human."
        return True, "generate_performance_report allowed."

    # ----------------------------------------------------------------------
    # static_compliance_scan – no extra restrictions
    if tool == "static_compliance_scan":
        return True, "static_compliance_scan allowed."

    # ----------------------------------------------------------------------
    # Any other tool not explicitly covered is allowed
    return True, f"Tool '{tool}' is not restricted by policy."

